<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config.php';require_once dirname(__DIR__).'/lib/common.php';require_once dirname(__DIR__).'/lib/customs.php';require_once dirname(__DIR__).'/lib/customs_iopr.php';tp_admin_required();$pdo=tp_db();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$no=trim((string)($_POST['customs_cargo_no']??''));try{if(!$id)throw new RuntimeException('대상 선박이 없습니다.');if(!tp_customs_valid_carg_no($no))throw new RuntimeException('관세청 cargMtNo는 15~19자리입니다. 해수부 mrNum 11자리를 그대로 입력하지 마세요.');$c=tp_customs_lookup_cargo($no);$pdo->prepare('UPDATE tp_vessels SET customs_cargo_no=?,customs_product_name=?,customs_progress_status=?,customs_total_weight=?,customs_weight_unit=?,customs_package_count=?,customs_last_checked_at=NOW(),customs_error=NULL,customs_raw_xml=?,tesla_flag=IF(?,1,tesla_flag),cargo_status=IF(?=1,?,cargo_status) WHERE id=?')->execute([$no,$c['product_name'],$c['progress_status'],$c['total_weight']?:null,$c['weight_unit'],$c['package_count']?:null,$c['raw'],$c['tesla_match'],$c['tesla_match'],$c['progress_status'],$id]);$msg='관세청 조회가 완료되었습니다.'.($c['tesla_match']?' TESLA 품명이 확인되었습니다.':'');}catch(Throwable $e){$err=$e->getMessage();if($id)$pdo->prepare('UPDATE tp_vessels SET customs_error=?,customs_last_checked_at=NOW() WHERE id=?')->execute([$err,$id]);}}
$rows=$pdo->query("SELECT * FROM tp_vessels WHERE is_vehicle_carrier=1 ORDER BY china_origin_flag DESC,COALESCE(eta,first_seen_at) DESC LIMIT 300")->fetchAll();
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>자동차운반선 후보</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f6f8}.card{border:0;border-radius:16px}code{word-break:break-all}</style></head><body><div class="container py-4" style="max-width:1200px"><div class="d-flex justify-content-between align-items-center"><div><h2 class="fw-bold">자동차운반선 후보</h2><p class="text-secondary">v1.8.1 · 해수부 + API024 교차검증 + 화물연결 진단</p></div><div><a class="btn btn-outline-dark" href="cargo_link.php">화물연결 진단</a> <a class="btn btn-outline-dark" href="iopr_test.php">API024 테스트</a> <a class="btn btn-outline-dark" href="customs_test.php">API001 테스트</a> <a class="btn btn-outline-dark" href="index.php">관리자</a></div></div><?php if($msg):?><div class="alert alert-success"><?=h($msg)?></div><?php endif?><?php if($err):?><div class="alert alert-danger"><?=h($err)?></div><?php endif?><div class="alert alert-warning"><b>중요:</b> 해수부의 <code>mrNum</code>은 현재 응답에서 11자리인 경우가 있으나, 관세청 API001은 cargMtNo(15~19자리) 또는 MBL/HBL로 조회합니다. 해수부 mrNum(MRN) 11자리는 별도 식별자이므로 임의 변환하지 않습니다. MBL/HBL 테스트는 관세청 API 테스트 화면을 이용하세요.</div><?php foreach($rows as $r):?><div class="card shadow-sm mb-3"><div class="card-body"><div class="d-flex justify-content-between flex-wrap gap-2"><div><b class="fs-5"><?=h($r['vessel_name'])?></b> <?php if($r['china_origin_flag']):?><span class="badge text-bg-danger">상하이 출항 · Tesla 추적</span><?php else:?><span class="badge text-bg-warning">자동차운반선</span><?php endif?> <?php if($r['tesla_flag']):?><span class="badge text-bg-dark">TESLA 확인</span><?php endif?></div><div><?=h($r['eta'])?></div></div><div class="row mt-3 small"><div class="col-md-3"><b>전출항지</b><br><?=h($r['origin_port'])?></div><div class="col-md-3"><b>양하톤</b><br><?=h($r['landing_ton'])?></div><div class="col-md-3"><b>해수부 mrNum</b><br><code><?=h($r['manifest_no'])?></code></div><div class="col-md-3"><b>관세청 cargMtNo</b><br><code><?=h($r['customs_cargo_no'])?></code></div></div><?php if(!empty($r['customs_iopr_last_checked_at'])):?><div class="alert alert-info mt-3 mb-2 small"><b>API024 교차검증:</b> <?=!empty($r['customs_iopr_verified'])?'일치':'미확인/불일치'?> · 관세청 출발항 <?=h($r['customs_iopr_departure_port']?:'-')?> · 입항 <?=h($r['customs_iopr_arrival_at']?:'-')?> · 제출번호 <code><?=h($r['customs_iopr_submission_no']?:'-')?></code> · <?=(!empty($r['customs_iopr_submission_no']) && $r['customs_iopr_submission_no']===$r['manifest_no'])?'해수부 mrNum과 동일':'mrNum 비교 필요'?></div><?php endif?><?php if($r['customs_product_name']||$r['customs_progress_status']):?><div class="alert alert-light border mt-3 mb-2"><b>관세청:</b> 품명 <?=h($r['customs_product_name']?:'-')?> · 상태 <?=h($r['customs_progress_status']?:'-')?> · <?=h($r['customs_total_weight'])?> <?=h($r['customs_weight_unit'])?> · <?=h($r['customs_package_count'])?>개</div><?php endif?><form method="post" class="row g-2 mt-1"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="col-md-9"><input class="form-control" name="customs_cargo_no" value="<?=h($r['customs_cargo_no'])?>" placeholder="관세청 화물관리번호(cargMtNo) 15~19자리"></div><div class="col-md-3"><button class="btn btn-dark w-100">관세청 조회/저장</button></div></form><?php if($r['customs_error']):?><div class="text-danger small mt-2"><?=h($r['customs_error'])?></div><?php endif?></div></div><?php endforeach?></div></body></html>
